:root {
  --bg: #0c0c13;
  --nav: #202331;
  --hero: #0d0d15;
  --line: rgba(125, 132, 156, 0.24);
  --text: #f6f6fb;
  --muted: #ececf4;
  --button: #6170ee;
  --button-hover: #7080ff;
  --purple: #785cf7;
  --blue: #1f9dff;
  --teal: #51b8b0;
  --ink: #f6f6fb;
  --deep: #30294f;
  --soft: #202331;
  --red: #e31b2f;
  --section-space: clamp(42px, 3.8vw, 58px);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

section[id] {
  scroll-margin-top: 88px;
}

body {
  margin: 0;
  background:
    radial-gradient(circle at 15% 110%, rgba(124, 78, 220, 0.2), transparent 24rem),
    radial-gradient(circle at 85% 104%, rgba(20, 131, 179, 0.2), transparent 25rem),
    var(--bg);
  color: var(--text);
  font-family:
    var(--font-inter), ui-sans-serif, system-ui, -apple-system,
    BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

.navigation-progress { position: fixed; top: 0; right: 0; left: 0; z-index: 9999; height: 4px; background: linear-gradient(90deg, #ff2d55, #ff7a00 55%, #ffe45c); box-shadow: 0 0 12px rgba(255, 88, 32, 0.9), 0 2px 18px rgba(255, 196, 38, 0.55); opacity: 0; transform: scaleX(0); transform-origin: left; pointer-events: none; }
.navigation-progress.is-loading { opacity: 1; animation: navigation-progress-loading 1400ms cubic-bezier(0.2, 0.7, 0.25, 1) forwards; }
.navigation-progress.is-complete { opacity: 0; transform: scaleX(1); transition: transform 180ms ease, opacity 260ms ease 80ms; }
@keyframes navigation-progress-loading {
  0% { transform: scaleX(0); }
  45% { transform: scaleX(0.48); }
  100% { transform: scaleX(0.84); }
}

a {
  color: inherit;
  text-decoration: none;
}

svg {
  display: block;
}

/* Authentication */
.auth-page {
  position: relative;
  isolation: isolate;
  min-height: 100svh;
  overflow: hidden;
  background:
    radial-gradient(circle at 12% 38%, rgba(44, 112, 220, 0.28), transparent 32rem),
    radial-gradient(circle at 88% 72%, rgba(42, 198, 190, 0.16), transparent 30rem),
    linear-gradient(135deg, #0b1222 0%, #11182b 48%, #0a1421 100%);
  color: #f8f9ff;
}

.auth-glow {
  position: absolute;
  z-index: 0;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  filter: blur(110px);
  pointer-events: none;
}
.webscan-section-heading, .webscan-capability-grid, .webscan-workflow-inner, .webscan-coverage-panel, .webscan-cta > * { position: relative; z-index: 1; }

.auth-glow-one { top: 16%; left: -180px; background: rgba(31, 157, 255, 0.24); }
.auth-glow-two { right: -160px; bottom: -100px; background: rgba(57, 202, 191, 0.2); }

.auth-wave-field {
  position: absolute;
  z-index: 0;
  right: -7%;
  bottom: -4%;
  left: -7%;
  height: 58%;
  overflow: hidden;
  opacity: 0.4;
  pointer-events: none;
  mask-image: linear-gradient(180deg, transparent 0, #000 20%, #000 88%, transparent 100%);
}

