@media (max-width: 720px) {
  .hybrid-scanner-page .hybrid-scanner-hero {
    min-height: auto;
  }

  .hybrid-scanner-page .hybrid-scanner-heading p,
  .hybrid-scanner-page .hybrid-scanner-features-copy > p,
  .hybrid-scanner-page .hybrid-scanner-workflow-heading > p,
