    min-height: auto;
  }

  .hybrid-scanner-page .hybrid-scanner-card-stage article {
    min-height: 140px;
  }

  .hybrid-scanner-page .hybrid-scanner-card-stage article h3,
  .hybrid-scanner-page .hybrid-scanner-feature-points h3,
  .hybrid-scanner-page .hybrid-scanner-reporting-benefit h3 {
    font-size: 16px;
  }

  .hybrid-scanner-page .hybrid-scanner-card-stage article p,
  .hybrid-scanner-page .hybrid-scanner-feature-points p,
  .hybrid-scanner-page .hybrid-scanner-reporting-benefit p,
