.auth-wave-field::after {
  position: absolute;
  right: 5%;
  bottom: -42%;
  left: 5%;
  height: 78%;
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(87, 72, 235, 0.3), rgba(45, 184, 206, 0.12) 46%, transparent 72%);
  filter: blur(35px);
  content: "";
}

.auth-wave-field svg {
  width: 114%;
  height: 100%;
  transform: translateX(-6%);
}

.auth-wave {
  fill: none;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.auth-wave-one { stroke: #3279ff; stroke-width: 7; opacity: 0.78; transform: translateY(-38px); }
.auth-wave-two { stroke: #2db8ce; stroke-width: 4; opacity: 0.62; transform: translateY(-12px); }
.auth-wave-three { stroke: #625cff; stroke-width: 6; opacity: 0.72; transform: translateY(18px); }
.auth-wave-four { stroke: #388fe8; stroke-width: 8; opacity: 0.5; transform: translateY(48px); }
.auth-wave-five { stroke: #39cfc4; stroke-width: 4; opacity: 0.64; transform: translateY(78px); }

.auth-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(100% - 48px, 1320px);
  height: 72px;
  margin: 0 auto;
  border-bottom: 1px solid rgba(151, 162, 193, 0.16);
}

.auth-logo {
  display: flex;
  align-items: center;
  width: 158px;
  height: 60px;
  overflow: hidden;
}

.auth-logo img {
  width: 168px;
  height: 162px;
  object-fit: contain;
  flex: none;
}

.auth-header-action {
  display: flex;
  align-items: center;
  gap: 16px;
  color: #c9d0df;
  font-size: 14px;
  font-weight: 550;
}

.auth-header-action a {
  padding: 10px 17px;
  border: 1px solid rgba(124, 139, 184, 0.42);
  border-radius: 8px;
  color: #fff;
  font-weight: 750;
  transition: border-color 180ms ease, background 180ms ease;
}

.auth-header-action a:hover { border-color: #6374ee; background: rgba(97, 112, 238, 0.1); }

.auth-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(440px, 500px);
  align-items: start;
  gap: clamp(56px, 6vw, 96px);
  width: min(100% - 48px, 1240px);
  min-height: calc(100svh - 72px);
  margin: 0 auto;
  padding: 28px 0 38px;
}

.auth-story {
  max-width: 600px;
  padding-left: clamp(0px, 1.4vw, 18px);
  padding-top: 10px;
}

.auth-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
  color: #65d8d0;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.auth-eyebrow > span { width: 26px; height: 1px; background: #65d8d0; }

.auth-story h1 {
  margin: 0;
  color: #f8faff;
  font-size: clamp(40px, 4.4vw, 60px);
  font-weight: 730;
  line-height: 1.02;
  letter-spacing: -0.055em;
  text-wrap: balance;
  text-shadow: 0 2px 30px rgba(53, 113, 255, 0.08);
}

.auth-story > p {
  max-width: 570px;
  margin: 17px 0 0;
  color: #c3cad9;
  font-size: clamp(15px, 1.2vw, 17px);
  line-height: 1.65;
}

.auth-benefits { display: grid; gap: 11px; margin-top: 25px; }
.auth-benefits > div { display: flex; align-items: flex-start; gap: 13px; color: #c5ccda; font-size: 14px; line-height: 1.6; }
.auth-benefits svg { width: 21px; height: 21px; flex: 0 0 auto; color: #65d8d0; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.auth-benefits strong { color: #f5f7ff; font-weight: 760; }

.auth-trust-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 28px;
  color: #9ca6bb;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.auth-trust-row > span:nth-child(2) { width: 3px; height: 3px; border-radius: 50%; background: #4d586f; }

.auth-card-wrap { position: relative; }
.auth-card-wrap::before {
  position: absolute;
  inset: -1px;
  z-index: -1;
  border-radius: 19px;
  content: "";
  background: linear-gradient(135deg, rgba(101, 216, 208, 0.52), rgba(97, 112, 238, 0.12) 42%, rgba(97, 112, 238, 0.45));
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.4), 0 0 55px rgba(58, 110, 230, 0.1);
}

.auth-card {
  padding: clamp(24px, 2.5vw, 34px);
  border: 1px solid rgba(151, 164, 202, 0.1);
  border-radius: 18px;
  background: linear-gradient(145deg, rgba(28, 34, 50, 0.99), rgba(17, 21, 34, 0.99));
  backdrop-filter: blur(20px);
}

.auth-card-heading { display: flex; align-items: center; gap: 15px; }
.auth-card-icon { display: grid; place-items: center; width: 42px; height: 42px; flex: 0 0 auto; border: 1px solid rgba(101, 216, 208, 0.35); border-radius: 11px; color: #65d8d0; background: rgba(101, 216, 208, 0.07); }
.auth-card-icon svg { width: 23px; height: 23px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.auth-card-heading p { margin: 0 0 4px; color: #65d8d0; font-size: 10px; font-weight: 850; letter-spacing: 0.16em; }
.auth-card h2 { margin: 0; color: #f8faff; font-size: clamp(24px, 2vw, 29px); font-weight: 760; line-height: 1.15; letter-spacing: -0.035em; }
.auth-card-intro { margin: 12px 0 18px; color: #b6bece; font-size: 13px; line-height: 1.55; }

.auth-social-row { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; }
.auth-social-row button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 42px;
  border: 1px solid rgba(139, 149, 180, 0.28);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.025);
  color: #f0f2f8;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: border-color 180ms ease, background 180ms ease, transform 180ms ease;
}
.auth-social-row button:hover { border-color: rgba(101, 216, 208, 0.6); background: rgba(101, 216, 208, 0.05); transform: translateY(-1px); }
.auth-google { color: #fff; font-size: 15px; font-weight: 850; }
.auth-microsoft { display: grid; grid-template-columns: 5px 5px; gap: 1px; }
.auth-microsoft i { display: block; width: 5px; height: 5px; background: #6374ee; }
.auth-microsoft i:nth-child(2), .auth-microsoft i:nth-child(3) { background: #65d8d0; }

.auth-divider { display: flex; align-items: center; gap: 12px; margin: 16px 0; color: #9aa3b6; font-size: 11px; }
.auth-divider::before, .auth-divider::after { height: 1px; flex: 1; content: ""; background: rgba(139, 149, 180, 0.18); }

.auth-form { display: grid; gap: 13px; }
.auth-form > label, .auth-field-row label { display: grid; gap: 8px; color: #eef0f7; font-size: 12px; font-weight: 720; }
.auth-field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.auth-form input:not([type="checkbox"]) {
  width: 100%;
  height: 44px;
  padding: 0 14px;
  border: 1px solid rgba(139, 149, 180, 0.27);
  border-radius: 8px;
  outline: none;
  background: rgba(7, 10, 18, 0.68);
  color: #fff;
  font: inherit;
  font-size: 14px;
  transition: border-color 180ms ease, box-shadow 180ms ease;
}
.auth-form input::placeholder { color: #7d879c; }
.auth-form input:focus { border-color: #6678ee; box-shadow: 0 0 0 3px rgba(97, 112, 238, 0.13); }
.auth-password-field { position: relative; display: block; }
.auth-password-field input { padding-right: 48px !important; }
.auth-password-field button { position: absolute; top: 50%; right: 12px; padding: 4px; border: 0; background: transparent; color: #7f889d; cursor: pointer; transform: translateY(-50%); }
.auth-password-field button:hover { color: #dfe3ef; }
.auth-password-field svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }

.auth-check { display: flex !important; grid-template-columns: none !important; align-items: flex-start; gap: 9px !important; color: #b4bccd !important; font-size: 11px !important; font-weight: 500 !important; line-height: 1.5; cursor: pointer; }
.auth-check input { width: 15px; height: 15px; margin: 1px 0 0; accent-color: #6374ee; }
.auth-check a, .auth-form-options > a { color: #7f8fff; font-weight: 700; }
.auth-form-options { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.auth-form-options > a { font-size: 11px; }

.auth-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 46px;
  padding: 0 18px;
  border: 0;
  border-radius: 8px;
  background: linear-gradient(110deg, #5869ec, #6d7cf4);
  color: #fff;
  font: inherit;
  font-size: 14px;
  font-weight: 820;
  box-shadow: 0 12px 30px rgba(71, 88, 222, 0.24);
  cursor: pointer;
  transition: transform 180ms ease, box-shadow 180ms ease, filter 180ms ease;
}
.auth-submit:hover { transform: translateY(-2px); filter: brightness(1.07); box-shadow: 0 16px 34px rgba(71, 88, 222, 0.32); }
.auth-form-notice { margin: -5px 0 0; color: #79d8cf; font-size: 11px; line-height: 1.5; text-align: center; }
.auth-switch { margin: 16px 0 0; color: #b0b8c9; font-size: 12px; text-align: center; }
.auth-switch a { color: #7f8fff; font-weight: 780; }

@media (max-width: 960px) {
  .auth-layout { grid-template-columns: 1fr; gap: 34px; max-width: 600px; padding-top: 38px; }
  .auth-story { text-align: center; }
  .auth-story > p { margin-right: auto; margin-left: auto; }
  .auth-benefits { max-width: 510px; margin-right: auto; margin-left: auto; text-align: left; }
  .auth-trust-row { justify-content: center; }
}

@media (max-width: 560px) {
  .auth-header { width: min(100% - 30px, 1320px); }
  .auth-header-action span { display: none; }
  .auth-layout { width: min(100% - 28px, 600px); padding: 36px 0 46px; }
  .auth-story h1 { font-size: clamp(38px, 12vw, 50px); }
  .auth-story > p { font-size: 15px; }
  .auth-benefits { margin-top: 30px; }
  .auth-trust-row { display: none; }
  .auth-card { padding: 25px 20px; }
  .auth-social-row, .auth-field-row { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  .auth-page *, .auth-page *::before, .auth-page *::after { scroll-behavior: auto !important; transition-duration: 0.01ms !important; }
}

/* Refined authentication layout */
