.webscan-final-cta-copy > p { max-width: 620px; margin: 20px 0 0; color: #b3bdcb; font-size: 14px; line-height: 1.7; }
.webscan-final-cta-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 10px; margin-top: 26px; }
.webscan-final-cta-actions > a { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 18px; border-radius: 8px; font-size: 12px; font-weight: 780; transition: transform 200ms ease, border-color 200ms ease, background 200ms ease; }
.webscan-final-cta-actions > a:first-child { gap: 13px; border: 2px solid transparent; color: #f7f9ff; background: linear-gradient(#101827, #101827) padding-box, linear-gradient(90deg, #62d8d0, #2b9cff, #7b61ff, #ff4d8d, #62d8d0) border-box; background-size: 100% 100%, 300% 100%; animation: webscan-cta-border 3.2s linear infinite; }
.webscan-final-cta-actions > a:last-child { border: 1px solid rgba(156, 174, 202, 0.34); color: #ecf0f6; background: rgba(11, 17, 27, 0.5); }
