.webscan-click-cursor { position: relative; display: grid; place-items: center; width: 18px; height: 18px; animation: webscan-cursor-click 1.6s ease-in-out infinite; }
.webscan-click-cursor svg { width: 17px; height: 17px; fill: currentColor; }
.webscan-click-cursor::after { position: absolute; top: 1px; right: 0; width: 8px; height: 8px; border: 1px solid #62d8d0; border-radius: 50%; content: ""; opacity: 0; animation: webscan-click-pulse 1.6s ease-out infinite; }
.webscan-final-cta-details { padding-left: 38px; border-left: 1px solid rgba(129, 148, 179, 0.24); }
.webscan-final-cta-details h3 { margin: 0; color: #f2f5f9; font-size: 24px; line-height: 1.25; letter-spacing: -0.03em; }
.webscan-final-cta-details > p { margin: 12px 0 0; color: #aab4c4; font-size: 13px; line-height: 1.62; }
.webscan-final-cta-details ul { display: grid; gap: 0; margin: 20px 0 0; padding: 0; border-top: 1px solid rgba(129, 148, 179, 0.2); list-style: none; }
.webscan-final-cta-details li { display: grid; grid-template-columns: 18px 1fr; align-items: center; gap: 11px; min-height: 38px; border-bottom: 1px solid rgba(129, 148, 179, 0.2); color: #d5dbe5; font-size: 12px; font-weight: 620; }
.webscan-final-cta-details li svg { width: 16px; height: 16px; color: #62d8d0; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.webscan-final-cta-details small { display: block; margin-top: 18px; padding: 11px 13px; border-left: 2px solid rgba(98, 216, 208, 0.58); color: #929eaf; background: rgba(98, 216, 208, 0.045); font-size: 10px; line-height: 1.55; }
@keyframes webscan-cta-border {
  from { background-position: 0 0, 0% 50%; }
  to { background-position: 0 0, 300% 50%; }
}
@keyframes webscan-cursor-click {
  0%, 30%, 100% { transform: translate(2px, 2px) scale(1); }
  45% { transform: translate(0, 0) scale(0.88); }
  58% { transform: translate(0, 0) scale(1); }
}
@keyframes webscan-click-pulse {
  0%, 38% { opacity: 0; transform: scale(0.35); }
  48% { opacity: 0.9; }
  72%, 100% { opacity: 0; transform: scale(2.1); }
}
@media (prefers-reduced-motion: reduce) {
  .webscan-final-cta-actions > a:first-child, .webscan-click-cursor, .webscan-click-cursor::after { animation: none; }
}

