.site-shell {
  min-height: 100vh;
  overflow: hidden;
  padding-top: 88px;
}

.scroll-reveal-section {
  opacity: 0;
  transform: translateY(34px);
  transition:
    opacity 720ms ease,
    transform 720ms cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.scroll-reveal-section.is-visible {
  opacity: 1;
  transform: none;
  will-change: auto;
}

.scroll-reveal-item {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 660ms ease var(--reveal-delay, 0ms),
    transform 660ms cubic-bezier(0.22, 1, 0.36, 1) var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

.scroll-reveal-section.is-visible .scroll-reveal-item {
  opacity: 1;
  transform: none;
  will-change: auto;
}

body.nav-open {
  overflow: hidden;
}

.navbar {
  position: fixed;
  top: 0;
  right: 0;
  left: 0;
  z-index: 100;
  isolation: isolate;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(24px, 3vw, 52px);
  width: 100%;
  height: 88px;
  min-height: 88px;
  padding: 8px clamp(24px, 4vw, 72px);
  border-bottom: 1px solid rgba(157, 163, 188, 0.22);
  background: rgba(20, 23, 34, 0.96);
  color: var(--text);
  font-family: Inter, "Segoe UI", ui-sans-serif, system-ui, sans-serif;
  font-feature-settings: "kern" 1, "liga" 1;
  text-rendering: optimizeLegibility;
  box-shadow: 0 12px 38px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(18px);
  transform: translateZ(0);
}

.navbar::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 2px;
  content: "";
