.hero-section {
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: flex-start;
  width: 100%;
  min-height: calc(100svh - 88px);
  padding: clamp(22px, 2.2vw, 34px) clamp(24px, 4vw, 68px) 24px;
  overflow: hidden;
  background:
    linear-gradient(135deg, rgba(227, 27, 47, 0.08) 0%, transparent 30%),
    linear-gradient(118deg, transparent 34%, rgba(81, 184, 176, 0.13) 68%, transparent 88%),
    linear-gradient(155deg, transparent 52%, rgba(97, 112, 238, 0.16) 100%),
    #f3f5f7;
}

.hero-grid {
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0.55;
  background-image:
    linear-gradient(rgba(76, 108, 150, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(76, 108, 150, 0.055) 1px, transparent 1px);
  background-position: 0 0;
  background-size: 48px 48px;
  mask-image: linear-gradient(90deg, transparent 0%, black 24%, black 100%);
}

.trusted-section::after,
.workflow-section::after,
.surface-section::after,
.challenge-section::after,
.solution-section::after,
.dashboard-section::after,
.faq-section::after,
.cta-section::after {
  position: absolute;
  inset: 0;
  z-index: 0;
  content: "";
  opacity: 0.62;
  background-image:
    repeating-linear-gradient(90deg, rgba(103, 117, 165, 0.06) 0, rgba(103, 117, 165, 0.06) 1px, transparent 1px, transparent 3px),
    repeating-linear-gradient(0deg, rgba(103, 117, 165, 0.04) 0, rgba(103, 117, 165, 0.04) 1px, transparent 1px, transparent 4px);
  background-size: 3px 100%, 100% 4px;
  pointer-events: none;
}

.hero-carousel {
  position: relative;
  z-index: 2;
  width: min(100%, 1460px);
  margin: 0 auto;
}

.hero-carousel-stage {
  display: grid;
  min-width: 0;
}

.hero-slide {
  grid-area: 1 / 1;
  display: grid;
  grid-template-columns: minmax(350px, 0.78fr) minmax(520px, 1.22fr);
  gap: clamp(28px, 3.5vw, 58px);
  align-items: stretch;
  width: 100%;
  min-width: 0;
  min-height: clamp(560px, calc(100svh - 190px), 700px);
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transform: translateY(10px);
  transition:
    opacity 420ms ease,
    transform 420ms ease,
    visibility 420ms ease;
}

.hero-slide.active {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.hero-copy {
  position: relative;
  z-index: 2;
  display: grid;
  justify-items: start;
  align-self: start;
  width: 100%;
  min-width: 0;
  padding: 0;
  text-align: left;
}

.hero-slide.active .hero-copy {
  animation: heroCopyIn 700ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.hero-eyebrow {
  display: inline-flex;
