  transform-origin: left;
}

.hero-secondary:hover::after {
  transform: scaleX(0.55);
}

.hero-visual {
  position: relative;
  isolation: isolate;
  --visual-accent: 81, 184, 176;
  --visual-base: #e7ebf0;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  min-height: 100%;
  margin: 0;
  overflow: visible;
  background: transparent;
  clip-path: none;
}

.hero-visual::before {
  display: none;
}

.hero-visual::after {
  display: none;
}

.hero-visual-2 {
