.hero-visual img {
  z-index: 1;
  object-fit: contain;
  object-position: center;
  padding: 8px 0 0;
  filter: drop-shadow(0 26px 34px rgba(0, 0, 0, 0.38));
  animation: none;
}

.hero-controls {
  position: absolute;
  bottom: 0;
