    linear-gradient(180deg, rgba(20, 185, 154, 0.95), rgba(63, 80, 204, 0.78)) border-box;
  box-shadow:
    0 0 28px rgba(20, 185, 154, 0.12),
    0 24px 58px rgba(0, 0, 0, 0.3);
}

.dashboard-video-card::before {
  position: absolute;
  inset: 0;
  content: "";
  background:
    linear-gradient(rgba(103, 117, 165, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(103, 117, 165, 0.055) 1px, transparent 1px);
  background-size: 42px 42px;
  pointer-events: none;
}

.dashboard-video-topbar {
  position: absolute;
  top: 14px;
  left: 18px;
  z-index: 2;
  display: flex;
  gap: 7px;
}

.dashboard-video-topbar span {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(232, 236, 248, 0.28);
}

.dashboard-video {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  border: 1px solid rgba(157, 163, 188, 0.16);
  background:
    radial-gradient(circle at 50% 35%, rgba(81, 184, 176, 0.13), transparent 34%),
    linear-gradient(145deg, #171923, #0b0d14);
  object-fit: cover;
}

.dashboard-grid {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-top: clamp(8px, 1vw, 16px);
}

.dashboard-card {
  position: relative;
  min-height: 232px;
  padding: 24px 22px 26px;
  overflow: hidden;
  border: 1px solid transparent;
  background:
    linear-gradient(145deg, rgba(18, 18, 28, 0.98) 0%, rgba(13, 15, 23, 0.98) 58%, rgba(26, 29, 50, 0.9) 100%) padding-box,
    linear-gradient(180deg, rgba(20, 185, 154, 0.95), rgba(63, 80, 204, 0.72)) border-box;
  box-shadow:
    0 0 0 1px rgba(20, 185, 154, 0.08),
    0 20px 42px rgba(0, 0, 0, 0.2);
}

.dashboard-card::after {
  position: absolute;
  right: -28%;
  bottom: -42%;
  width: 78%;
  height: 78%;
  content: "";
  background: radial-gradient(circle, rgba(95, 141, 255, 0.14), transparent 62%);
  pointer-events: none;
}

.dashboard-card-icon {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  color: var(--teal);
}

.dashboard-card-icon .mega-icon-svg {
  width: 25px;
  height: 25px;
}

.dashboard-card h3 {
  margin-top: 18px;
  color: #ffffff;
  font-size: clamp(20px, 1.55vw, 23px);
  font-weight: 550;
  line-height: 1.25;
  letter-spacing: 0;
}

.dashboard-card p {
  margin-top: 14px;
  color: rgba(232, 236, 248, 0.74);
  font-size: 15px;
  line-height: 1.58;
}

.faq-section {
  position: relative;
  overflow: hidden;
  padding: clamp(56px, 6vw, 90px) clamp(20px, 5vw, 82px);
  border-top: 1px solid rgba(157, 163, 188, 0.16);
  background: #11141c;
}

.faq-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(300px, 0.78fr) minmax(520px, 1.22fr);
  gap: clamp(34px, 6vw, 82px);
  align-items: start;
  width: min(100%, 1280px);
  margin: 0 auto;
}

.faq-heading {
  position: sticky;
  top: 112px;
  display: grid;
  justify-items: start;
}

.faq-kicker {
  color: var(--teal);
  font-size: 13px;
  font-weight: 900;
  line-height: 1.3;
  letter-spacing: 0.32em;
  text-transform: uppercase;
}

.faq-heading h2 {
  max-width: 540px;
  margin-top: 16px;
  color: #ffffff;
  font-size: clamp(34px, 4vw, 52px);
  font-weight: 400;
  line-height: 1.08;
  letter-spacing: 0;
}

.faq-heading p {
  max-width: 500px;
  margin-top: 22px;
  color: rgba(232, 236, 248, 0.76);
  font-size: clamp(16px, 1.25vw, 18px);
  line-height: 1.58;
}

.faq-list {
  display: grid;
  gap: 12px;
}

.faq-item {
  position: relative;
  overflow: hidden;
  border: 1px solid transparent;
  background:
    linear-gradient(145deg, rgba(18, 18, 28, 0.98) 0%, rgba(13, 15, 23, 0.98) 58%, rgba(26, 29, 50, 0.9) 100%) padding-box,
    linear-gradient(180deg, rgba(20, 185, 154, 0.95), rgba(63, 80, 204, 0.72)) border-box;
  box-shadow:
    0 0 0 1px rgba(20, 185, 154, 0.08),
    0 18px 38px rgba(0, 0, 0, 0.18);
}

.faq-item summary {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
  min-height: 82px;
  padding: 22px 24px;
  color: #ffffff;
  cursor: pointer;
  list-style: none;
}

.faq-item summary::-webkit-details-marker {
  display: none;
}

.faq-item summary::after {
  position: absolute;
  top: 28px;
  right: 24px;
  width: 26px;
  height: 26px;
  border: 1px solid rgba(232, 236, 248, 0.18);
  color: var(--teal);
  content: "+";
  display: grid;
  place-items: center;
  font-size: 20px;
  line-height: 1;
}

.faq-item[open] summary::after {
  content: "-";
}

.faq-item summary span {
  color: #5f8dff;
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
  letter-spacing: 0.12em;
}

.faq-item summary strong {
  max-width: calc(100% - 46px);
  font-size: clamp(18px, 1.5vw, 22px);
  font-weight: 600;
  line-height: 1.35;
}

.faq-item p {
  max-width: 780px;
  padding: 0 72px 26px 84px;
  color: rgba(232, 236, 248, 0.74);
  font-size: 16px;
  line-height: 1.62;
}

.cta-section {
  position: relative;
  overflow: hidden;
  padding: clamp(34px, 4vw, 54px) clamp(20px, 5vw, 82px);
  background: #0c0f16;
}

.cta-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: clamp(28px, 5vw, 72px);
  align-items: center;
  width: min(100%, 1240px);
  margin: 0 auto;
  padding: clamp(24px, 3vw, 36px);
  border: 1px solid transparent;
  border-radius: 2px;
  background:
    linear-gradient(135deg, rgba(25, 28, 39, 0.96), rgba(13, 15, 23, 0.98)) padding-box,
    linear-gradient(180deg, rgba(20, 185, 154, 0.95), rgba(63, 80, 204, 0.76)) border-box;
  box-shadow:
    0 0 0 1px rgba(20, 185, 154, 0.08),
    0 26px 64px rgba(0, 0, 0, 0.28);
}

.cta-inner::before {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  border-radius: inherit;
  content: "";
  background:
    radial-gradient(circle at 16% 22%, rgba(81, 184, 176, 0.13), transparent 24rem),
    radial-gradient(circle at 88% 78%, rgba(97, 112, 238, 0.16), transparent 26rem),
    linear-gradient(120deg, transparent 0 62%, rgba(97, 112, 238, 0.08) 62% 72%, transparent 72%);
  pointer-events: none;
}

.cta-copy,
.cta-actions {
  position: relative;
  z-index: 1;
}

.cta-kicker {
  display: block;
  color: var(--teal);
  font-size: 13px;
  font-weight: 900;
  line-height: 1.3;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.cta-copy h2 {
  max-width: 780px;
  margin-top: 10px;
  color: #ffffff;
  font-size: clamp(34px, 4vw, 54px);
  font-weight: 450;
  line-height: 1.08;
  letter-spacing: 0;
}

.cta-copy p {
  max-width: 720px;
  margin-top: 12px;
  color: rgba(232, 236, 248, 0.76);
  font-size: clamp(16px, 1.3vw, 18px);
  line-height: 1.58;
}

.cta-actions {
  display: flex;
  justify-content: end;
  min-width: min(100%, 268px);
}

.cta-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  min-width: 210px;
  min-height: 54px;
  padding: 0 24px;
  border: 1px solid rgba(97, 112, 238, 0.62);
  border-radius: 2px;
  background: var(--button);
  color: #ffffff;
  box-shadow: 0 16px 32px rgba(97, 112, 238, 0.25);
  font-size: 15px;
  font-weight: 900;
  line-height: 1;
  transition:
    transform 180ms ease,
    box-shadow 180ms ease;
}

.cta-primary:hover {
  transform: translateY(-2px);
  background: var(--button-hover);
  box-shadow: 0 20px 38px rgba(97, 112, 238, 0.32);
}

.footer-section {
  position: relative;
  overflow: hidden;
  min-height: 465px;
  padding: 28px 0 28px;
  border-top: 1px solid rgba(157, 163, 188, 0.16);
  background: #1d2029;
  color: #ffffff;
  font-family: Inter, "Segoe UI", ui-sans-serif, system-ui, sans-serif;
  font-feature-settings: "kern" 1, "liga" 1;
}

.footer-section::before {
  position: absolute;
  inset: auto 0 0;
  height: 1px;
  content: "";
  background: linear-gradient(90deg, var(--red), var(--teal), var(--button));
  pointer-events: none;
}

.footer-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(230px, 1.05fr) minmax(620px, 2.5fr) minmax(220px, 0.95fr);
  gap: clamp(28px, 3vw, 48px);
  width: min(100%, 1380px);
  min-height: 0;
  margin: 0 auto;
  padding-inline: clamp(28px, 4vw, 64px);
  isolation: isolate;
}

.footer-brand {
  position: relative;
  z-index: 1;
  display: grid;
  align-content: start;
  justify-items: start;
}

.footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 0;
  width: 240px;
  height: 82px;
  overflow: hidden;
  color: #ffffff;
  font-size: clamp(30px, 2.4vw, 38px);
  font-weight: 900;
  line-height: 1;
}

.footer-logo-image {
  flex: none;
  width: 240px;
  height: 240px;
  object-fit: cover;
  object-position: center;
}

.footer-brand h2 {
  max-width: 260px;
  margin-top: 14px;
  color: #f7f8fc;
  font-size: 18px;
  font-weight: 800;
  line-height: 1.35;
  letter-spacing: -0.015em;
}

.footer-brand p {
  max-width: 270px;
  margin-top: 8px;
  color: rgba(232, 236, 248, 0.8);
  font-size: 14px;
  font-weight: 450;
  line-height: 1.65;
}

.footer-contact {
  display: flex;
  margin-top: 12px;
}

.footer-contact a {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-height: 40px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #69d4ca;
  font-size: 13px;
  font-weight: 750;
  letter-spacing: 0.015em;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.footer-contact a:hover {
  color: #ffffff;
  transform: translateX(2px);
}

.footer-nav {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(20px, 2.4vw, 38px);
}

.footer-column h2 {
  color: #69d4ca;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.footer-column ul {
  display: grid;
  gap: 12px;
  margin: 18px 0 0;
  padding: 0;
  list-style: none;
}

.footer-column a {
  color: rgba(240, 243, 252, 0.78);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.footer-column a:hover {
  color: #8b9aff;
  transform: translateX(2px);
}

.footer-details {
  padding-left: clamp(22px, 2.5vw, 38px);
  border-left: 1px solid rgba(105, 212, 202, 0.24);
}

.footer-details h2 {
  color: #69d4ca;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.footer-details > a:not(.footer-details-action),
.footer-details p {
  display: block;
  margin-top: 20px;
  color: rgba(240, 243, 252, 0.8);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
}

.footer-details p {
  max-width: 240px;
  margin-top: 16px;
}

.footer-details-action {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  margin-top: 18px;
  padding: 0 14px;
  border: 1px solid rgba(97, 112, 238, 0.72);
  border-radius: 20px;
  background: rgba(97, 112, 238, 0.16);
  color: #ffffff;
  font-size: 13px;
  font-weight: 750;
  letter-spacing: 0.01em;
}

.footer-details-action:hover {
  border-color: #8b9aff;
  background: var(--button);
  color: #ffffff;
}

.footer-bottom {
  position: relative;
  z-index: 2;
  display: flex;
  grid-column: 1 / -1;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 34px;
  padding-top: 24px;
  border-top: 1px solid rgba(157, 163, 188, 0.24);
}

.footer-bottom p {
  color: rgba(232, 236, 248, 0.68);
  font-size: 12.5px;
  font-weight: 450;
  letter-spacing: 0.01em;
}

.footer-bottom div {
  display: flex;
  gap: 22px;
  align-items: center;
}

.footer-bottom a {
  color: rgba(232, 236, 248, 0.76);
  font-size: 12.5px;
  font-weight: 600;
  transition: color 180ms ease;
}

.footer-bottom a:hover {
  color: #69d4ca;
}

.scroll-reveal-item {
  transition:
    opacity 660ms ease var(--reveal-delay, 0ms),
    transform 660ms cubic-bezier(0.22, 1, 0.36, 1) var(--reveal-delay, 0ms);
}

@media (max-width: 1120px) {
  .navbar {
    gap: 18px;
    padding-inline: 24px;
  }

  .nav-links {
    gap: 18px;
    font-size: 14px;
  }

  .nav-actions {
    gap: 20px;
  }

  .nav-login,
  .nav-start {
    font-size: 15px;
  }

  .mega-content {
    grid-template-columns: 220px minmax(0, 1fr);
  }

  .mega-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .workflow-layout {
    grid-template-columns: minmax(205px, 0.85fr) minmax(360px, 1.35fr) minmax(205px, 0.85fr);
    gap: 20px;
  }

  .workflow-agent {
    grid-template-columns: 30px minmax(0, 1fr);
    gap: 10px;
    padding-left: 12px;
  }

  .surface-heading {
    grid-template-columns: minmax(300px, 0.8fr) minmax(400px, 1.2fr);
    gap: 54px;
  }

  .surface-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-width: 820px;
    margin-inline: auto;
  }

  .surface-card:nth-child(odd) {
    margin-top: 44px;
  }

  .challenge-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .challenge-card {
    min-height: 0;
  }

  .solution-inner {
    grid-template-columns: minmax(280px, 0.95fr) minmax(390px, 1.05fr);
    gap: 34px;
  }

  .solution-card {
    min-height: 0;
  }

  .dashboard-inner {
    grid-template-columns: 1fr;
  }

  .dashboard-video-card {
    width: min(100%, 900px);
  }

  .dashboard-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .faq-inner {
    grid-template-columns: 1fr;
    gap: 34px;
  }

  .faq-heading {
    position: relative;
    top: auto;
    max-width: 760px;
  }

  .cta-inner {
    grid-template-columns: 1fr;
  }

  .cta-actions {
    justify-content: start;
    width: min(100%, 260px);
  }

  .footer-inner {
    grid-template-columns: 1fr;
    gap: 38px;
    min-height: 0;
  }

  .footer-nav {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .footer-details {
    padding: 28px 0 0;
    border-top: 1px solid rgba(157, 163, 188, 0.2);
    border-left: 0;
  }

}

@media (max-width: 960px) {
  .site-shell {
    padding-top: 76px;
  }

  .navbar {
    gap: 18px;
    height: 76px;
    min-height: 76px;
    padding: 10px 18px;
  }

  .brand {
    gap: 9px;
    margin-right: auto;
    width: 128px;
    height: 60px;
  }

  .brand-logo {
    width: 128px;
    height: auto;
  }

  .brand-mark {
    width: 44px;
    height: 44px;
  }

  .brand-forge,
  .brand-slash,
  .brand-sec {
    font-size: 28px;
  }

  .nav-links {
    display: none;
  }

  .nav-actions {
    gap: 12px;
  }

  .nav-login {
    display: none;
  }

  .nav-start {
    min-height: 44px;
    font-size: 14px;
  }

  .mobile-toggle {
    display: inline-grid;
    place-items: center;
    width: 44px;
    height: 44px;
    padding: 0;
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.04);
    color: #ffffff;
    cursor: pointer;
  }

  .menu-glyph {
    position: relative;
    display: grid;
    gap: 5px;
    width: 20px;
  }

  .menu-glyph span {
    display: block;
    width: 100%;
    height: 2px;
    border-radius: 2px;
    background: currentColor;
    transition: transform 180ms ease, opacity 140ms ease;
  }

  .menu-glyph.is-open span:first-child {
    transform: translateY(7px) rotate(45deg);
  }

  .menu-glyph.is-open span:nth-child(2) {
    opacity: 0;
  }

  .menu-glyph.is-open span:last-child {
    transform: translateY(-7px) rotate(-45deg);
  }

  .mobile-menu {
    position: fixed;
    top: 76px;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 90;
    display: block;
    visibility: hidden;
    overflow-y: auto;
    background:
      linear-gradient(145deg, rgba(97, 112, 238, 0.07), transparent 38%),
      #12131d;
    opacity: 0;
    pointer-events: none;
    transform: translateY(-10px);
    transition:
      opacity 220ms ease,
      transform 220ms cubic-bezier(0.22, 1, 0.36, 1),
      visibility 0s linear 220ms;
  }

  .mobile-menu.is-open {
    visibility: visible;
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0);
    transition-delay: 0s;
  }

  .mobile-menu-inner {
    width: min(100%, 680px);
    margin: 0 auto;
    padding: 18px 20px 34px;
  }

  .mobile-nav-group,
  .mobile-nav-single {
    border-bottom: 1px solid rgba(255, 255, 255, 0.09);
  }

  .mobile-nav-trigger,
  .mobile-nav-single {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    min-height: 56px;
    padding: 0 4px;
    border: 0;
    background: transparent;
    color: #ffffff;
    font: inherit;
    font-size: 17px;
    font-weight: 850;
    text-align: left;
    cursor: pointer;
  }

  .mobile-accordion {
    display: grid;
    grid-template-rows: 0fr;
    opacity: 0;
    transition: grid-template-rows 240ms ease, opacity 180ms ease;
  }

  .mobile-accordion.is-open {
    grid-template-rows: 1fr;
    opacity: 1;
  }

  .mobile-accordion-inner {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 5px;
    min-height: 0;
    overflow: hidden;
    padding: 0 0 12px;
  }

  .mobile-menu-link {
    display: flex;
    gap: 11px;
    align-items: flex-start;
    min-width: 0;
    padding: 11px 8px;
    border-radius: 4px;
    transition: background 160ms ease;
  }

  .mobile-menu-link:hover,
  .mobile-menu-link:focus-visible {
    background: rgba(255, 255, 255, 0.05);
  }

  .mobile-menu-link .mega-icon {
    width: 36px;
    height: 36px;
  }

  .mobile-menu-link .mega-icon-svg {
    width: 18px;
    height: 18px;
  }

  .mobile-menu-link strong,
  .mobile-menu-link small {
    display: block;
  }

  .mobile-menu-link strong {
    color: #ffffff;
    font-size: 14px;
    line-height: 1.3;
  }

  .mobile-menu-link small {
    margin-top: 4px;
    color: rgba(236, 236, 244, 0.58);
    font-size: 12px;
    line-height: 1.4;
  }

  .mobile-menu-actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    padding: 24px 4px 0;
    font-weight: 850;
  }

  .mobile-menu-actions .nav-start {
    padding-inline: 4px;
  }

  .hero-section {
    min-height: calc(100svh - 76px);
    padding: 28px 28px 26px;
  }

  .hero-slide {
    grid-template-columns: 1fr;
    gap: 8px;
    min-height: 760px;
  }

  .hero-carousel {
    padding-bottom: 0;
  }

  .hero-copy {
    width: 100%;
    max-width: 700px;
  }

  .hero-actions {
