.apiscan-continuous { position:relative;overflow:hidden;padding:76px 24px 88px;border-bottom:1px solid rgba(92,139,150,.2);background:radial-gradient(circle at 84% 14%,rgba(42,102,220,.15),transparent 30%),radial-gradient(circle at 10% 88%,rgba(29,208,180,.1),transparent 34%),#050b10 }
