/* OS scanner hero — violet security palette */
.osscan-hero{background:radial-gradient(ellipse at 76% 42%,rgba(117,68,255,.28),transparent 34%),radial-gradient(ellipse at 22% 84%,rgba(124,58,237,.38),transparent 42%),linear-gradient(180deg,#030315 0%,#07051d 61%,#361396 100%)}
.osscan-hero::before{display:none;background:none}
.osscan-hero::after{content:"";position:absolute;right:0;bottom:0;left:0;z-index:-2;height:38%;background:linear-gradient(180deg,transparent,rgba(139,92,246,.35) 48%,rgba(196,181,253,.92) 100%);filter:saturate(1.15)}
.osscan-hero .osscan-kicker{color:#c4b5fd}.osscan-hero .osscan-kicker i{background:linear-gradient(90deg,#8b5cf6,transparent)}.osscan-hero h1 em{color:#bca6ff;text-shadow:0 0 40px rgba(139,92,246,.2)}.osscan-hero-copy>p{color:#b8b5c8}
.osscan-hero .osscan-actions a:first-child{color:#100827;background:#f5f1ff;box-shadow:0 12px 34px rgba(124,58,237,.28)}.osscan-hero .osscan-actions a:last-child{border-color:rgba(196,181,253,.32);background:rgba(14,10,35,.66)}.osscan-hero-trust{color:#a7a1bd}.osscan-hero-trust svg{stroke:#c4b5fd}
.osscan-orbit{border-color:rgba(196,181,253,.16)}.osscan-orbit i{border-color:rgba(196,181,253,.11)}
.osscan-hero .osscan-radar{border-color:rgba(167,139,250,.42);background:linear-gradient(145deg,rgba(21,16,48,.97),rgba(7,6,24,.99));box-shadow:0 38px 100px rgba(9,2,35,.58),0 0 70px rgba(124,58,237,.12)}.osscan-hero .osscan-radar-top{border-color:rgba(196,181,253,.16);color:#d5ccef}.osscan-hero .osscan-radar-top b{color:#c4b5fd}.osscan-hero .osscan-radar-body{background:radial-gradient(circle at center,rgba(139,92,246,.24),transparent 47%)}
.osscan-hero .osscan-rings i{border-color:rgba(196,181,253,.2)}.osscan-hero .osscan-rings i:nth-child(4){background:rgba(139,92,246,.15);box-shadow:0 0 46px rgba(139,92,246,.24)}.osscan-hero .osscan-rings::before,.osscan-hero .osscan-rings::after{background:rgba(196,181,253,.16)}.osscan-hero .osscan-radar-core,.osscan-hero .osscan-node{border-color:rgba(167,139,250,.56);background:#100c2a;box-shadow:0 0 0 7px rgba(139,92,246,.07)}.osscan-hero .osscan-radar-core{color:#ddd2ff}.osscan-hero .osscan-radar-core small,.osscan-hero .osscan-node small{color:#a69bbf}.osscan-hero .osscan-radar-stats{border-color:rgba(196,181,253,.16)}.osscan-hero .osscan-radar-stats div{border-color:rgba(196,181,253,.14)}.osscan-hero .osscan-radar-stats small{color:#9289aa}

/* Simplified OS hero content */
.osscan-hero-inner{display:flex;align-items:center;justify-content:center;width:min(100%,1100px);min-height:calc(100svh - 210px);margin:auto;text-align:center}
.osscan-hero-copy{display:flex;align-items:center;flex-direction:column;width:100%;max-width:920px}
.osscan-hero .osscan-kicker{justify-content:center}
.osscan-hero h1{max-width:900px;margin-top:24px;color:#f8f7ff;font-size:clamp(54px,7vw,94px);line-height:.98;letter-spacing:-.055em}
.osscan-hero h1{max-width:1000px;white-space:normal;font-size:clamp(48px,5.5vw,78px)}
.osscan-hero h1 em{display:block;color:#c4b5fd;text-shadow:none}
.osscan-hero-copy>p{max-width:720px;margin-top:28px;color:#d0cbe0;font-size:17px;line-height:1.72}
.osscan-hero .osscan-actions{justify-content:center;margin-top:32px}
.osscan-hero .osscan-actions a{min-width:190px;min-height:48px;padding:0 22px;border-radius:7px;font-size:13px;font-weight:850;transition:transform .2s ease,border-color .2s ease,background .2s ease}
.osscan-hero .osscan-actions a:first-child{gap:16px;color:#10072b;background:#f3efff;box-shadow:0 12px 30px rgba(124,58,237,.24)}
.osscan-hero .osscan-actions a:first-child>span{display:inline-flex;align-items:center;justify-content:center;font-size:15px}
.osscan-hero .osscan-actions .webscan-click-cursor{width:18px;height:18px}
.osscan-hero .osscan-actions .webscan-click-cursor svg{width:16px;height:16px;fill:#10072b}
.osscan-hero .osscan-actions a:last-child{border:1px solid rgba(216,205,255,.62);color:#fff;background:rgba(18,10,48,.88)}
.osscan-hero .osscan-actions a:hover{transform:translateY(-2px)}
.osscan-hero .osscan-actions .webscan-primary,.osscan-hero .osscan-actions .webscan-primary>span{color:#160b35}
.osscan-hero .osscan-actions .webscan-primary::after{background:#d9ccff}
.osscan-hero .osscan-actions .webscan-primary::before{background:linear-gradient(90deg,#8b5cf6,#d8caff,#8b5cf6);filter:blur(4px)}
.osscan-hero .osscan-actions .webscan-secondary,.osscan-hero .osscan-actions .webscan-secondary>span{color:#fff}
.osscan-hero .osscan-actions .webscan-secondary::after{background:#120b2b}
.osscan-hero .osscan-actions .webscan-secondary::before{background:linear-gradient(90deg,#6d43d9,#c4b5fd,#6d43d9);filter:blur(4px)}
.osscan-hero .osscan-actions .webscan-primary:active,.osscan-hero .osscan-actions .webscan-primary:active>span{color:#160b35}
.osscan-hero .osscan-actions .webscan-secondary:active,.osscan-hero .osscan-actions .webscan-secondary:active>span{color:#fff}

/* OS scanner journey readability */
.osscan-journey a{min-height:106px;grid-template-columns:42px 1fr;column-gap:16px;padding:24px 26px}
.osscan-journey a>span{width:40px;height:40px;font-size:11px}
.osscan-journey small{font-size:10px;line-height:1.2;letter-spacing:.12em}
.osscan-journey strong{margin-top:7px;font-size:15px;line-height:1.35}
@media(max-width:760px){.osscan-journey a{min-height:96px;grid-template-columns:36px 1fr;column-gap:12px;padding:18px}.osscan-journey a>span{width:34px;height:34px;font-size:10px}.osscan-journey small{font-size:9px}.osscan-journey strong{font-size:13px}}

/* Host and service visibility */
.osscan-coverage{position:relative;overflow:hidden;background:radial-gradient(circle at 8% 12%,rgba(72,231,211,.07),transparent 27%),linear-gradient(180deg,#070d12,#081118)}
.osscan-coverage::before{content:"";position:absolute;top:0;left:50%;width:min(92%,1280px);height:1px;background:linear-gradient(90deg,transparent,rgba(72,231,211,.52),transparent);transform:translateX(-50%)}
.osscan-coverage>.osscan-section-head,.osscan-coverage>.osscan-capability-grid,.osscan-coverage>.osscan-coverage-summary{position:relative}
.osscan-coverage .osscan-section-head{align-items:center}.osscan-coverage .osscan-section-number{margin-bottom:16px;color:#71888b}.osscan-coverage .osscan-section-head>p{padding-left:28px;border-left:1px solid rgba(72,231,211,.3);font-size:15px;line-height:1.8}
.osscan-coverage .osscan-capability-grid{grid-template-columns:repeat(6,minmax(0,1fr));gap:14px}
.osscan-coverage .osscan-capability-grid article{grid-column:span 2;display:flex;flex-direction:column;min-height:270px;padding:27px 28px;border-color:rgba(107,160,162,.24);background:linear-gradient(145deg,rgba(12,27,35,.98),rgba(6,15,21,.98));box-shadow:0 20px 45px rgba(0,0,0,.16)}
