/* Insights: structured text-first hero */
.insights-page-hero {
  position: relative;
  isolation: isolate;
  display: grid;
  align-items: center;
  min-height: 650px;
  padding: 128px clamp(28px, 6vw, 96px) 72px;
  overflow: hidden;
  color: #fff;
  background:
    radial-gradient(circle at 12% 12%, rgba(98, 78, 224, 0.2), transparent 31%),
    radial-gradient(circle at 86% 18%, rgba(52, 190, 181, 0.14), transparent 30%),
    radial-gradient(ellipse at 52% 112%, rgba(43, 98, 163, 0.24), transparent 48%),
    linear-gradient(135deg, #060912 0%, #08131c 48%, #07171d 100%);
}

.insights-page-hero::before {
  position: absolute;
  z-index: -2;
  inset: 0;
  background-image:
    linear-gradient(rgba(114, 152, 177, 0.065) 1px, transparent 1px),
    linear-gradient(90deg, rgba(114, 152, 177, 0.065) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: linear-gradient(180deg, transparent, #000 18%, #000 78%, transparent);
  content: "";
}

.insights-page-hero::after {
  position: absolute;
  z-index: -1;
  right: 8%;
  bottom: -210px;
  left: 8%;
  height: 320px;
  border: 1px solid rgba(94, 222, 214, 0.16);
  border-radius: 50%;
  box-shadow: 0 0 100px rgba(70, 88, 214, 0.18);
  content: "";
}

.insights-page-hero-content {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(340px, 0.65fr);
  align-items: end;
  gap: 54px clamp(56px, 8vw, 124px);
  width: min(100%, 1380px);
  margin: 0 auto;
  font-family: "Avenir Next", Avenir, "Trebuchet MS", "Segoe UI", sans-serif;
}

.insights-page-hero-copy,
.insights-page-hero-summary {
  min-width: 0;
}

.insights-page-hero-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  color: #69e2da;
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.insights-page-hero-kicker i {
  width: 34px;
  height: 1px;
  background: #69e2da;
}

.insights-page-hero h1 {
  max-width: 900px;
  margin: 22px 0 0;
  color: #f7fbfc;
  font-size: clamp(54px, 5.5vw, 82px);
  font-weight: 730;
  line-height: 0.98;
  letter-spacing: -0.055em;
  text-wrap: balance;
}

.insights-page-hero h1 span {
  display: block;
  color: #6fe0d9;
}

.insights-page-hero-summary {
  padding: 6px 0 8px 28px;
  border-left: 1px solid rgba(105, 226, 218, 0.32);
}

.insights-page-hero-summary > p {
  max-width: 520px;
  margin: 0;
  color: #afc1c8;
  font-size: 14px;
  line-height: 1.75;
}

.insights-page-hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 26px;
}

.insights-page-hero-actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 48px;
  padding: 0 20px;
  border: 1px solid #62dfd7;
  border-radius: 6px;
  color: #07191f;
  background: #62dfd7;
  font-size: 10px;
  font-weight: 850;
  text-decoration: none;
  transition: border-color 180ms ease, background 180ms ease, color 180ms ease, transform 180ms ease;
}

.insights-page-hero-actions a:last-child {
  border-color: rgba(255, 255, 255, 0.26);
  color: #eef7f8;
  background: rgba(255, 255, 255, 0.045);
}

.insights-page-hero-actions a:hover {
  border-color: #8cf2eb;
  transform: translateY(-2px);
}

.insights-page-hero-topics {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 2px;
  border-top: 1px solid rgba(121, 164, 179, 0.2);
  border-bottom: 1px solid rgba(121, 164, 179, 0.2);
}

.insights-page-hero-topics > span {
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 72px;
  padding: 0 22px;
  border-right: 1px solid rgba(121, 164, 179, 0.2);
  color: #c3d0d5;
  font-size: 9px;
  font-weight: 820;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.insights-page-hero-topics > span:first-child {
  padding-left: 0;
}

.insights-page-hero-topics > span:last-child {
  border-right: 0;
}

.insights-page-hero-topics b {
  color: #5ddbd3;
  font: 850 9px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
}

@media (max-width: 980px) {
  .insights-page-hero {
    min-height: 620px;
  }

  .insights-page-hero-content {
    grid-template-columns: 1fr;
    align-items: start;
    gap: 30px;
  }

  .insights-page-hero-summary {
    max-width: 700px;
  }

  .insights-page-hero-topics {
    margin-top: 16px;
  }
}

@media (max-width: 760px) {
  .insights-page-hero {
    min-height: auto;
    padding: 108px 18px 54px;
  }

  .insights-page-hero::before {
    background-size: 42px 42px;
  }

  .insights-page-hero-content {
    gap: 26px;
  }

  .insights-page-hero h1 {
    margin-top: 18px;
    font-size: clamp(42px, 12vw, 58px);
    line-height: 1.02;
  }

  .insights-page-hero-summary {
    padding: 0;
    border-left: 0;
  }

  .insights-page-hero-summary > p {
    font-size: 13px;
    line-height: 1.7;
  }

  .insights-page-hero-actions {
    align-items: stretch;
    margin-top: 22px;
    flex-direction: column;
  }

  .insights-page-hero-actions a {
    width: 100%;
  }

  .insights-page-hero-topics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    margin-top: 8px;
  }

  .insights-page-hero-topics > span {
    min-height: 58px;
    padding: 0 12px;
    border-bottom: 1px solid rgba(121, 164, 179, 0.2);
    font-size: 8px;
  }

  .insights-page-hero-topics > span:first-child {
    padding-left: 12px;
  }

  .insights-page-hero-topics > span:nth-child(2) {
    border-right: 0;
  }

  .insights-page-hero-topics > span:nth-last-child(-n + 2) {
    border-bottom: 0;
  }
}

/* Keep the continuous-pentesting policy section static, crisp, and readable. */
.continuous-page .controlled-testing :is(
  .control-framework-head > *,
  .control-framework-flow > div,
  .control-framework-grid > article
) {
  opacity: 1 !important;
  visibility: visible !important;
  filter: none !important;
  transform: none !important;
  animation: none !important;
  transition: none !important;
  will-change: auto !important;
}

.continuous-page .control-framework-head .controlled-testing-label {
  color: #68e2da;
  font-size: 11px;
  font-weight: 800;
}

.continuous-page .control-framework-head h2 {
