/* Insights: reference-led editorial showcase hero */
.insights-showcase-hero {
  position: relative;
  isolation: isolate;
  display: grid;
  align-items: center;
  min-height: 690px;
  padding: 142px clamp(28px, 6vw, 96px) 82px;
  overflow: hidden;
  color: #f7fbff;
  background: linear-gradient(145deg, #071621 0%, #0a1e2b 52%, #071821 100%);
}

.insights-showcase-hero::before {
  display: none;
}

.insights-showcase-hero::after {
  display: none;
}

.insights-showcase-orbit {
  display: none;
}

.insights-showcase-orbit::after {
  display: none;
}

.insights-showcase-inner {
  width: min(100%, 1100px);
  margin: 0 auto;
}

.insights-showcase-intro {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  text-align: center;
  flex-direction: column;
}

.insights-showcase-kicker {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  min-height: 32px;
  padding: 0 14px;
  border: 1px solid rgba(121, 226, 220, 0.24);
  border-radius: 999px;
  color: #83e8e2;
  background: rgba(115, 224, 217, 0.055);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.insights-showcase-kicker i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 14px currentColor;
}

.insights-showcase-intro h1 {
  max-width: 980px;
  margin: 28px 0 0;
  color: #fff;
  font-size: clamp(48px, 5.3vw, 76px);
  font-weight: 700;
  line-height: 0.98;
  letter-spacing: -0.058em;
  text-wrap: balance;
}

.insights-showcase-intro h1 span {
  display: block;
  color: #75ded8;
}

.insights-showcase-intro > p {
  max-width: 700px;
  margin: 25px 0 0;
  color: #b3c6ce;
  font-size: 14px;
  line-height: 1.72;
  text-wrap: balance;
}

.insights-showcase-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 11px;
  margin-top: 31px;
}

.insights-showcase-actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  min-height: 49px;
  padding: 0 21px;
  border: 1px solid #72ded8;
  border-radius: 7px;
  color: #062025;
  background: #72ded8;
  font-size: 10px;
  font-weight: 850;
  text-decoration: none;
  transition: border-color 180ms ease, background 180ms ease, color 180ms ease, transform 180ms ease;
}

.insights-showcase-actions a:last-child {
  border-color: rgba(216, 238, 240, 0.28);
  color: #eef8f8;
  background: rgba(255, 255, 255, 0.04);
  backdrop-filter: blur(10px);
}

.insights-showcase-actions a:hover {
  border-color: #99f3ed;
  background: #99f3ed;
  color: #06191e;
  transform: translateY(-2px);
}

.insights-showcase-topics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  width: min(100%, 880px);
  margin-top: 54px;
  border: 1px solid rgba(141, 183, 196, 0.17);
  border-radius: 10px;
  background: rgba(8, 29, 39, 0.55);
  box-shadow: 0 18px 50px rgba(1, 9, 15, 0.16);
  backdrop-filter: blur(12px);
}

.insights-showcase-topics span {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  min-height: 66px;
  padding: 0 17px;
  border-right: 1px solid rgba(141, 183, 196, 0.17);
  color: #c0d0d6;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.insights-showcase-topics span:last-child {
  border-right: 0;
}

.insights-showcase-topics b {
  color: #6ddbd4;
  font: 850 8px/1 ui-monospace, SFMono-Regular, Menlo, monospace;
}

@media (max-width: 760px) {
  .insights-showcase-hero {
    min-height: auto;
    padding: 112px 18px 58px;
  }

  .insights-showcase-orbit {
    display: none;
  }

  .insights-showcase-intro h1 {
    margin-top: 23px;
    font-size: clamp(38px, 10.8vw, 52px);
    line-height: 1;
  }

  .insights-showcase-intro > p {
    margin-top: 21px;
    font-size: 13px;
    line-height: 1.68;
  }

  .insights-showcase-actions {
    align-items: stretch;
    flex-direction: column;
    width: 100%;
    max-width: 420px;
  }

  .insights-showcase-actions a {
    width: 100%;
  }

  .insights-showcase-topics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    margin-top: 40px;
  }

  .insights-showcase-topics span {
    min-height: 58px;
    padding: 0 10px;
    border-bottom: 1px solid rgba(141, 183, 196, 0.17);
  }

  .insights-showcase-topics span:nth-child(2) {
    border-right: 0;
  }

  .insights-showcase-topics span:nth-last-child(-n + 2) {
    border-bottom: 0;
  }
}

@media (max-width: 420px) {
  .insights-showcase-kicker {
    font-size: 8px;
  }

  .insights-showcase-topics span {
    gap: 8px;
    font-size: 7px;
  }
}

