main.landing-page > .phonepe-hero .hero-scan-finding:nth-child(2) { animation-delay: 1.72s; }
main.landing-page > .phonepe-hero .hero-scan-finding:nth-child(3) { animation-delay: 2.02s; }
main.landing-page > .phonepe-hero .hero-scan-finding:nth-child(4) { animation-delay: 2.32s; }
main.landing-page > .phonepe-hero .hero-scan-finding:nth-child(5) { animation-delay: 2.62s; }
main.landing-page > .phonepe-hero .hero-scan-summary { animation-delay: 3.02s; }
main.landing-page > .phonepe-hero .hero-scan-priority { animation-delay: 3.38s; }
main.landing-page > .phonepe-hero .hero-scan-evidence { animation-delay: 3.72s; }
main.landing-page > .phonepe-hero .hero-scan-complete { animation-delay: 4.08s; }

@keyframes heroScanTerminalIn {
  from { opacity: 0; transform: translate3d(36px, 0, 0) scale(0.98); }
  to { opacity: 1; transform: none; }
}

@keyframes heroScanReveal {
  from { opacity: 0; transform: translateY(7px); }
  to { opacity: 1; transform: none; }
}

@keyframes heroScanProgress {
  from { transform: scaleX(0.02); }
  to { transform: scaleX(1); }
}

@keyframes heroScanSweep {
  0% { top: 45px; opacity: 0; }
  12% { opacity: 0.72; }
  76% { top: calc(100% - 20px); opacity: 0.2; }
  86%, 100% { top: calc(100% - 20px); opacity: 0; }
}

@keyframes heroScanPulse {
  0%, 100% { opacity: 0.48; transform: scale(0.88); }
  50% { opacity: 1; transform: scale(1); }
}

@keyframes heroScanCursor {
  0%, 48% { opacity: 1; }
  49%, 100% { opacity: 0; }
}

