/* Forgot password: focused, secure account-recovery experience. */
main.auth-page-forgot {
  isolation: isolate;
  min-height: 100svh;
  overflow-x: hidden;
  overflow-y: auto;
  background:
    radial-gradient(ellipse 60% 70% at 5% 108%, rgba(73, 56, 255, 0.58), transparent 68%),
    radial-gradient(ellipse 54% 64% at 100% 100%, rgba(53, 177, 202, 0.32), transparent 70%),
    linear-gradient(135deg, #03050a 0%, #080b15 52%, #0a111d 100%);
}

main.auth-page-forgot::before {
  position: absolute;
  z-index: 0;
  inset: 0;
  content: "";
  opacity: 0.45;
  background-image:
    linear-gradient(rgba(158, 176, 219, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(158, 176, 219, 0.045) 1px, transparent 1px),
    radial-gradient(circle at center, rgba(150, 175, 233, 0.17) 0 1px, transparent 1.4px);
  background-size: 52px 52px, 52px 52px, 26px 26px;
  mask-image: linear-gradient(90deg, #000, rgba(0, 0, 0, 0.38) 68%, transparent);
  pointer-events: none;
}

main.auth-page-forgot::after {
  position: absolute;
  z-index: 0;
  right: -8%;
  bottom: -36%;
  left: -8%;
  height: 70%;
  border-radius: 50% 50% 0 0 / 40% 40% 0 0;
  content: "";
  background:
    radial-gradient(ellipse at 18% 20%, rgba(74, 55, 255, 0.42), transparent 38%),
    radial-gradient(ellipse at 82% 18%, rgba(79, 197, 213, 0.34), transparent 42%),
    linear-gradient(180deg, rgba(78, 84, 200, 0.08), rgba(122, 183, 210, 0.2));
  filter: blur(16px);
  pointer-events: none;
}

.auth-page-forgot .auth-glow {
  display: none;
}

.auth-page-forgot > .forgot-header,
.auth-page-forgot > .forgot-layout {
  position: relative;
  z-index: 2;
}

main.auth-page-forgot > .forgot-layout {
  display: grid;
  grid-template-columns: minmax(0, 640px) minmax(430px, 500px);
  align-items: center;
  gap: clamp(44px, 4vw, 60px);
  width: min(100% - 56px, 1200px);
  min-height: calc(100svh - 78px);
  margin: 0 auto;
  padding: 40px 0 56px;
}

.forgot-story {
  width: 100%;
  max-width: 650px;
}

.forgot-story h1 {
  max-width: 650px;
  margin: 0;
  color: #f8faff;
  font-size: clamp(46px, 4.4vw, 64px);
  font-weight: 700;
  line-height: 1.04;
  letter-spacing: -0.052em;
  text-wrap: balance;
}

.forgot-story > p:not(.forgot-security-note) {
  max-width: 600px;
  margin: 20px 0 0;
  color: rgba(231, 237, 249, 0.82);
  font-size: 17px;
  line-height: 1.68;
}

.forgot-story-body {
  display: grid;
  grid-template-columns: minmax(220px, 0.84fr) minmax(280px, 1.16fr);
  gap: 14px;
  align-items: stretch;
  max-width: 650px;
  margin-top: 32px;
}

.forgot-visual {
  position: relative;
  min-height: 248px;
  margin: 0;
  overflow: hidden;
  border: 1px solid rgba(145, 128, 242, 0.3);
  border-radius: 14px;
  background: #0b0d12;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 22px 48px rgba(0, 0, 0, 0.24);
}

.forgot-visual::after {
  position: absolute;
  inset: 0;
  z-index: 1;
  content: "";
  background:
    linear-gradient(180deg, transparent 58%, rgba(5, 7, 12, 0.82) 100%),
    linear-gradient(135deg, rgba(128, 86, 230, 0.08), transparent 52%, rgba(49, 172, 119, 0.07));
  pointer-events: none;
}

.forgot-visual img {
  object-fit: contain;
  object-position: center;
}

.forgot-visual figcaption {
  position: absolute;
  z-index: 2;
  right: 14px;
  bottom: 12px;
  left: 14px;
  display: flex;
  align-items: center;
  gap: 7px;
  color: rgba(242, 245, 250, 0.88);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.forgot-visual figcaption > span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #59d19a;
  box-shadow: 0 0 12px rgba(89, 209, 154, 0.72);
}

.forgot-steps {
  position: relative;
  display: grid;
  gap: 10px;
  max-width: 590px;
  margin-top: 0;
}

.forgot-steps > div {
  position: relative;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 15px;
  align-items: center;
  min-height: 76px;
  padding: 12px 18px 12px 12px;
  border: 1px solid rgba(146, 160, 201, 0.16);
  border-radius: 12px;
  background: linear-gradient(105deg, rgba(24, 28, 45, 0.72), rgba(14, 18, 31, 0.48));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
  backdrop-filter: blur(12px);
}

.forgot-steps > div > span {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(101, 216, 208, 0.36);
  border-radius: 10px;
  color: #70ddd5;
  background: rgba(101, 216, 208, 0.07);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.08em;
}

.forgot-steps strong {
  display: block;
  color: #f5f7ff;
  font-size: 14px;
  font-weight: 760;
  line-height: 1.35;
}

.forgot-steps p {
  margin: 4px 0 0;
  color: #aeb8ca;
  font-size: 13px;
  line-height: 1.5;
}

.forgot-security-note {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 22px 0 0;
  color: #9faabc;
  font-size: 12px;
  line-height: 1.5;
}

.forgot-security-note svg {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  fill: none;
  stroke: #65d8d0;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.forgot-card-wrap {
  position: relative;
  width: 100%;
}

.forgot-card-wrap::before {
  position: absolute;
  inset: -1px;
  z-index: -1;
  border-radius: 23px;
  content: "";
  background: linear-gradient(145deg, rgba(112, 102, 244, 0.66), rgba(97, 112, 238, 0.12) 46%, rgba(84, 207, 199, 0.5));
  box-shadow: 0 36px 90px rgba(0, 0, 0, 0.48), 0 0 70px rgba(76, 69, 213, 0.13);
}

.forgot-card {
  position: relative;
  overflow: hidden;
  padding: clamp(32px, 3vw, 42px);
  border: 1px solid rgba(157, 169, 205, 0.1);
  border-radius: 22px;
  background:
    radial-gradient(circle at 90% 3%, rgba(98, 87, 232, 0.12), transparent 15rem),
    linear-gradient(145deg, rgba(27, 30, 47, 0.98), rgba(12, 16, 28, 0.99));
  backdrop-filter: blur(22px);
}

.forgot-card::after {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 1px;
  content: "";
  background: linear-gradient(90deg, transparent, rgba(151, 143, 255, 0.75), rgba(101, 216, 208, 0.58), transparent);
}

.forgot-card-icon {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  margin-bottom: 22px;
  border: 1px solid rgba(101, 216, 208, 0.4);
  border-radius: 14px;
  color: #65d8d0;
  background: linear-gradient(145deg, rgba(101, 216, 208, 0.12), rgba(97, 112, 238, 0.08));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 10px 26px rgba(40, 170, 165, 0.08);
}

.forgot-card-icon svg {
  width: 27px;
  height: 27px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.65;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.forgot-card-label {
  margin: 0 0 8px;
  color: #69dcd4;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.18em;
}

.forgot-card h2 {
  margin: 0;
  color: #f8faff;
  font-size: clamp(29px, 2.4vw, 36px);
  font-weight: 740;
  line-height: 1.15;
  letter-spacing: -0.04em;
}

.forgot-card-intro {
  max-width: 410px;
  margin: 14px 0 26px;
  color: #b7c0d1;
  font-size: 14px;
  line-height: 1.65;
}

.forgot-form {
  display: grid;
}

.forgot-form > label {
  margin-bottom: 9px;
  color: #edf1f8;
  font-size: 13px;
  font-weight: 720;
}

.forgot-email-field {
  position: relative;
  display: block;
}

.forgot-email-field > svg {
  position: absolute;
  z-index: 1;
  top: 50%;
  left: 15px;
  width: 19px;
  height: 19px;
  fill: none;
  stroke: #737e94;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  transform: translateY(-50%);
  pointer-events: none;
}

.forgot-email-field input {
  width: 100%;
  height: 50px;
  padding: 0 15px 0 46px;
  border: 1px solid rgba(211, 219, 237, 0.84);
  border-radius: 9px;
  outline: none;
  color: #171a24;
  background: #f5f6f9;
  font: inherit;
  font-size: 14px;
  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.forgot-email-field input::placeholder {
  color: #7d8698;
}

.forgot-email-field input:focus {
  border-color: #817cf1;
  background: #ffffff;
  box-shadow: 0 0 0 4px rgba(122, 117, 242, 0.16);
}

.forgot-email-field:focus-within > svg {
  stroke: #585ed1;
}

.forgot-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  width: 100%;
  min-height: 50px;
  margin-top: 16px;
  padding: 0 22px;
  border: 1px solid rgba(200, 207, 255, 0.3);
  border-radius: 9px;
  color: #ffffff;
  background: linear-gradient(110deg, #565be0, #746ef0);
  box-shadow: 0 13px 30px rgba(67, 72, 207, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.16);
  font: inherit;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 180ms ease, filter 180ms ease, box-shadow 180ms ease;
