.not-found-motion {
  position: absolute;
  z-index: -1;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.not-found-motion::before {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(78vw, 1120px);
  height: min(46vw, 520px);
  border: 1px solid rgba(81, 205, 218, 0.1);
  border-radius: 50%;
  content: "";
  background: radial-gradient(ellipse at center, rgba(76, 91, 232, 0.14), transparent 64%);
  transform: translate(-50%, -50%);
  animation: notFoundCoreBreathe 4.8s ease-in-out infinite;
}

.not-found-motion::after {
  position: absolute;
  inset: 0;
  content: "";
  opacity: 0.4;
  background:
    linear-gradient(transparent 0 48%, rgba(91, 235, 229, 0.08) 49%, transparent 52%),
