/* 404: alternate breach-scan animation, replacing the ring/glitch treatment. */
.not-found-page::before {
  opacity: 0.22;
  background-size: 46px 46px;
  animation: notFoundAltGridSlide 20s linear infinite;
}

.not-found-page .not-found-ascii {
  position: absolute;
  overflow: visible;
  animation: notFoundAlt404Charge 5.8s ease-in-out infinite;
}

.not-found-page .not-found-ascii::before,
.not-found-page .not-found-ascii::after {
  position: absolute;
  inset: 0;
  content: "404";
  color: transparent;
  pointer-events: none;
}

.not-found-page .not-found-ascii::before {
  -webkit-text-stroke: 2px rgba(82, 235, 227, 0.2);
  clip-path: inset(0 0 64% 0);
  transform: translateX(-10px);
  animation: notFoundAltSliceTop 4.4s cubic-bezier(0.3, 0, 0.1, 1) infinite;
}

.not-found-page .not-found-ascii::after {
