  animation: notFoundAltSliceBottom 4.4s cubic-bezier(0.3, 0, 0.1, 1) infinite;
}

.not-found-motion {
  z-index: -1;
}

.not-found-motion::before {
  top: 50%;
  left: 50%;
  width: min(86vw, 1180px);
