    linear-gradient(180deg, transparent 0 21%, rgba(83, 218, 216, 0.44) 21% 22%, transparent 22% 49%, rgba(105, 99, 255, 0.36) 49% 50%, transparent 50% 79%, rgba(83, 218, 216, 0.32) 79% 80%, transparent 80%);
  background-size: 220px 100%, 260px 100%, 300px 100%, 100% 100%;
  filter: drop-shadow(0 0 14px rgba(83, 218, 216, 0.18));
  transform: translateY(-50%);
  animation: notFoundAltCircuitRun 5.2s linear infinite;
}

.not-found-circuit-left {
