/* Change password: structured account-security page. */
.change-password-page {
  position: relative;
  isolation: isolate;
  min-height: 100svh;
  overflow-x: hidden;
  overflow-y: auto;
  color: #f7f9ff;
  background:
    radial-gradient(ellipse 72% 58% at 50% 112%, rgba(69, 53, 238, 0.42), transparent 68%),
    linear-gradient(135deg, #03050a 0%, #080b15 52%, #07111d 100%);
}

.change-password-grid {
  position: absolute;
  z-index: 0;
  inset: 0;
  opacity: 0.38;
  background-image:
    linear-gradient(rgba(158, 176, 219, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(158, 176, 219, 0.045) 1px, transparent 1px),
    radial-gradient(circle at center, rgba(127, 145, 220, 0.15) 0 1px, transparent 1.4px);
  background-size: 52px 52px, 52px 52px, 26px 26px;
  mask-image: linear-gradient(90deg, #000, rgba(0, 0, 0, 0.68) 74%, transparent);
  pointer-events: none;
}

.change-password-glow {
  position: absolute;
  z-index: 0;
  right: -6%;
  left: -6%;
  height: 42%;
  pointer-events: none;
}

.change-password-glow-one {
  bottom: -20%;
  background:
    linear-gradient(90deg, rgba(69, 53, 238, 0.18), transparent 32%, rgba(68, 189, 206, 0.18)),
    linear-gradient(180deg, transparent, rgba(95, 121, 229, 0.14));
  filter: blur(14px);
}

.change-password-glow-two {
  top: -28%;
  background: linear-gradient(90deg, transparent, rgba(64, 214, 202, 0.08), transparent);
  filter: blur(28px);
}

.change-password-header,
.change-password-layout {
  position: relative;
  z-index: 2;
}

.change-password-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: min(100% - 56px, 1320px);
  height: 78px;
  margin: 0 auto;
  border-bottom: 1px solid rgba(139, 158, 201, 0.13);
}

.change-password-logo {
  display: flex;
  align-items: center;
  width: 158px;
  height: 64px;
  overflow: hidden;
}

.change-password-logo img {
  width: 168px;
  height: auto;
}

.change-password-header-action {
  display: flex;
  align-items: center;
  gap: 16px;
  color: #e8edf8;
  font-size: 14px;
  font-weight: 700;
}

.change-password-header-action a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 0 20px;
  border: 1px solid rgba(151, 162, 205, 0.24);
  border-radius: 8px;
  color: #ffffff;
  background: rgba(12, 17, 30, 0.62);
}

.change-password-layout {
  display: grid;
  grid-template-columns: minmax(0, 610px) minmax(420px, 500px);
  align-items: center;
  justify-content: center;
  gap: 64px;
  width: min(100% - 64px, 1220px);
  min-height: calc(100svh - 78px);
  margin: 0 auto;
  padding: 40px 0 56px;
}

.change-password-story h1 {
  max-width: 590px;
  margin: 20px 0 0;
  color: #f8faff;
  font-size: 58px;
  font-weight: 740;
  line-height: 1.04;
  letter-spacing: 0;
  text-wrap: balance;
}

.change-password-story > p {
  max-width: 560px;
  margin: 20px 0 0;
  color: rgba(231, 237, 249, 0.84);
  font-size: 17px;
  line-height: 1.68;
}

.change-password-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: #65d8d0;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.change-password-eyebrow span {
  width: 30px;
  height: 1px;
  background: currentColor;
}

.change-password-proof {
  display: grid;
  gap: 12px;
  max-width: 590px;
  margin-top: 34px;
}

.change-password-proof > div {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  column-gap: 15px;
  align-items: center;
  min-height: 78px;
  padding: 13px 17px 13px 12px;
  border: 1px solid rgba(146, 160, 201, 0.16);
  border-radius: 8px;
  background: linear-gradient(105deg, rgba(24, 28, 45, 0.72), rgba(14, 18, 31, 0.48));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
  backdrop-filter: blur(12px);
}

.change-password-proof > div > span {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid rgba(101, 216, 208, 0.36);
  border-radius: 8px;
  color: #70ddd5;
  background: rgba(101, 216, 208, 0.07);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.08em;
}

.change-password-proof strong {
  display: block;
  color: #f5f7ff;
  font-size: 14px;
  font-weight: 760;
  line-height: 1.35;
}

.change-password-proof p {
  margin: 4px 0 0;
  color: #aeb8ca;
  font-size: 13px;
  line-height: 1.5;
}

.change-password-note {
  display: flex;
  align-items: center;
  gap: 10px;
  max-width: 560px;
  margin-top: 24px;
  color: #a8b3c7;
  font-size: 13px;
  line-height: 1.55;
}

.change-password-note svg,
.change-password-card-icon svg,
.change-password-footer svg,
.change-password-input-wrap svg {
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.change-password-note svg {
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
  color: #65d8d0;
  stroke-width: 1.8;
}

.change-password-card-wrap {
  position: relative;
  width: 100%;
}

.change-password-card-wrap::before {
  position: absolute;
  inset: -1px;
  z-index: -1;
  border-radius: 13px;
  content: "";
  background: linear-gradient(145deg, rgba(112, 102, 244, 0.66), rgba(97, 112, 238, 0.12) 46%, rgba(84, 207, 199, 0.5));
  box-shadow: 0 34px 88px rgba(0, 0, 0, 0.46), 0 0 70px rgba(76, 69, 213, 0.13);
