.change-password-card {
  position: relative;
  overflow: hidden;
  padding: 34px;
  border: 1px solid rgba(157, 169, 205, 0.1);
  border-radius: 12px;
  background:
    radial-gradient(circle at 90% 3%, rgba(98, 87, 232, 0.12), transparent 15rem),
    linear-gradient(145deg, rgba(27, 30, 47, 0.98), rgba(12, 16, 28, 0.99));
  backdrop-filter: blur(22px);
}

.change-password-card::after {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 1px;
  content: "";
  background: linear-gradient(90deg, transparent, rgba(151, 143, 255, 0.75), rgba(101, 216, 208, 0.58), transparent);
}

.change-password-card-icon {
  display: grid;
  place-items: center;
  width: 50px;
  height: 50px;
  margin-bottom: 22px;
  border: 1px solid rgba(101, 216, 208, 0.4);
  border-radius: 8px;
  color: #65d8d0;
  background: linear-gradient(145deg, rgba(101, 216, 208, 0.12), rgba(97, 112, 238, 0.08));
}

.change-password-card-icon svg {
  width: 26px;
  height: 26px;
  stroke-width: 1.65;
}

.change-password-card-label {
  margin: 0 0 8px;
  color: #69dcd4;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.change-password-card h2 {
  margin: 0;
  color: #f8faff;
  font-size: 34px;
  font-weight: 740;
  line-height: 1.15;
  letter-spacing: 0;
}

.change-password-card-intro {
  max-width: 420px;
  margin: 13px 0 24px;
  color: #b7c0d1;
  font-size: 14px;
  line-height: 1.65;
}

.change-password-form {
  display: grid;
  gap: 15px;
}

.change-password-field > span:first-child {
  display: block;
  margin-bottom: 8px;
  color: #edf1f8;
  font-size: 13px;
  font-weight: 720;
}

.change-password-input-wrap {
  position: relative;
  display: block;
}

.change-password-input-wrap input {
  width: 100%;
  height: 50px;
  padding: 0 48px 0 15px;
  border: 1px solid rgba(211, 219, 237, 0.82);
  border-radius: 8px;
  outline: none;
  color: #171a24;
  background: #f5f6f9;
  font: inherit;
  font-size: 14px;
  transition: border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.change-password-input-wrap input::placeholder {
  color: #7d8698;
}

.change-password-input-wrap input:focus {
  border-color: #817cf1;
  background: #ffffff;
  box-shadow: 0 0 0 4px rgba(122, 117, 242, 0.16);
}

.change-password-input-wrap button {
  position: absolute;
  top: 50%;
  right: 12px;
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 0;
  color: #737e94;
  background: transparent;
  cursor: pointer;
  transform: translateY(-50%);
}

.change-password-input-wrap button:hover {
  color: #585ed1;
}

.change-password-input-wrap svg {
  width: 18px;
  height: 18px;
  stroke-width: 1.7;
}

.change-password-strength {
  display: grid;
  gap: 9px;
  margin-top: 2px;
}

.change-password-strength > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #aeb8ca;
  font-size: 12px;
}

.change-password-strength strong {
  color: #f3f7ff;
}

.change-password-strength i {
  display: block;
  height: 6px;
  max-width: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #615be4, #65d8d0);
  box-shadow: 0 0 20px rgba(101, 216, 208, 0.2);
  transition: width 180ms ease;
}

.change-password-rules {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.change-password-rules li {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #9da8bc;
  font-size: 12px;
  line-height: 1.35;
}

.change-password-rules li span {
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  border: 1px solid rgba(157, 169, 205, 0.44);
  border-radius: 50%;
}

.change-password-rules li.is-passed {
  color: #d5f5f2;
}

.change-password-rules li.is-passed span {
  border-color: #65d8d0;
  background: #65d8d0;
  box-shadow: 0 0 10px rgba(101, 216, 208, 0.6);
}

.change-password-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  min-height: 50px;
  margin-top: 4px;
  padding: 0 22px;
  border: 1px solid rgba(200, 207, 255, 0.3);
  border-radius: 8px;
  color: #ffffff;
  background: linear-gradient(110deg, #565be0, #746ef0);
  box-shadow: 0 13px 30px rgba(67, 72, 207, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.16);
  font: inherit;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 180ms ease, filter 180ms ease, box-shadow 180ms ease;
}

.change-password-submit:hover {
  filter: brightness(1.08);
  transform: translateY(-2px);
  box-shadow: 0 17px 34px rgba(67, 72, 207, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.change-password-status {
  margin: 0;
  padding: 11px 12px;
  border: 1px solid rgba(101, 216, 208, 0.24);
  border-radius: 8px;
  color: #bceeea;
  background: rgba(101, 216, 208, 0.07);
  font-size: 12px;
  line-height: 1.5;
}

.change-password-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid rgba(146, 157, 191, 0.15);
}

.change-password-footer > a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #eef1fa;
  font-size: 12px;
  font-weight: 750;
}

.change-password-footer svg {
  width: 17px;
  height: 17px;
  stroke-width: 1.8;
}

.change-password-footer > span {
  color: #919caf;
  font-size: 11px;
}

.change-password-footer > span a {
  color: #7fded7;
  font-weight: 700;
}

.change-password-header-action a:focus-visible,
.change-password-input-wrap button:focus-visible,
.change-password-submit:focus-visible,
.change-password-footer a:focus-visible {
  outline: 3px solid rgba(101, 216, 208, 0.7);
  outline-offset: 3px;
}

@media (min-width: 1500px) {
  .change-password-layout {
    grid-template-columns: 620px 500px;
    gap: 78px;
  }
}

@media (max-width: 1080px) {
  .change-password-page {
    overflow-y: auto;
  }

  .change-password-layout {
    grid-template-columns: 1fr;
    gap: 42px;
    width: min(100% - 40px, 650px);
    padding: 48px 0 60px;
  }

  .change-password-story {
    text-align: center;
  }

  .change-password-story h1,
  .change-password-story > p,
  .change-password-proof,
  .change-password-note {
    margin-right: auto;
    margin-left: auto;
  }

  .change-password-proof,
  .change-password-note {
    text-align: left;
  }
}

@media (max-width: 560px) {
  .change-password-header {
    width: min(100% - 28px, 1320px);
    height: 70px;
  }

  .change-password-header-action span {
    display: none;
  }

  .change-password-header-action a {
    min-height: 38px;
    padding: 0 15px;
  }

  .change-password-logo {
    width: 138px;
  }

  .change-password-logo img {
    width: 148px;
  }

  .change-password-layout {
    width: min(100% - 26px, 600px);
    padding: 34px 0 44px;
  }

  .change-password-story h1 {
    font-size: 42px;
  }

  .change-password-story > p {
    font-size: 16px;
  }

  .change-password-proof > div {
    grid-template-columns: 40px minmax(0, 1fr);
    min-height: 72px;
    padding: 10px 12px 10px 10px;
  }

  .change-password-card {
    padding: 28px 20px;
  }

  .change-password-rules {
    grid-template-columns: 1fr;
  }

  .change-password-footer {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .change-password-input-wrap input,
  .change-password-strength i,
  .change-password-submit {
    transition: none;
  }
}

