/* Privacy Policy page */
.privacy-policy-page {
  min-height: 100svh;
  color: #eef7f8;
  background:
    radial-gradient(circle at 12% 12%, rgba(94, 220, 211, 0.12), transparent 32%),
    radial-gradient(circle at 90% 4%, rgba(104, 88, 237, 0.16), transparent 34%),
    linear-gradient(180deg, #070b14 0%, #0a111c 44%, #08141a 100%);
  font-family: "Avenir Next", Avenir, "Trebuchet MS", "Segoe UI", sans-serif;
}

.privacy-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(390px, 0.64fr);
  align-items: end;
  gap: clamp(48px, 7vw, 96px);
  width: min(calc(100% - 56px), 1240px);
  margin: 0 auto;
  padding: 148px 0 70px;
