.privacy-hero-copy > span,
.privacy-closing span {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: #64e2d4;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.privacy-hero-copy > span i,
.privacy-closing span i {
  width: 34px;
  height: 1px;
  background: currentColor;
}

.privacy-hero h1 {
  max-width: 820px;
  margin: 20px 0 0;
  color: #ffffff;
  font-size: clamp(44px, 5vw, 72px);
  font-weight: 760;
  line-height: 1.02;
  letter-spacing: -0.055em;
