.privacy-hero-copy > p {
  max-width: 760px;
  margin: 24px 0 0;
  color: #c6d5dc;
  font-size: 18px;
  line-height: 1.72;
}

.privacy-hero-meta {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  margin-top: 30px;
  padding: 10px 14px;
  border: 1px solid rgba(128, 227, 216, 0.2);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.055);
}

.privacy-hero-meta span {
  color: #8da3ad;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.privacy-hero-meta b {
  color: #ffffff;
  font-size: 13px;
}

.privacy-summary {
