/* Global cookie preference notice. */
.cookie-consent {
  position: fixed;
  z-index: 10000;
  right: auto;
  bottom: clamp(18px, 3vw, 38px);
  left: 50%;
  width: min(680px, calc(100vw - 36px));
  overflow: hidden;
  padding: 22px 24px;
  border: 1px solid transparent;
  border-radius: 18px;
  color: #f4f8fa;
  background:
    radial-gradient(circle at 100% 0, rgba(93, 97, 238, 0.22), transparent 42%) padding-box,
    linear-gradient(145deg, rgba(7, 19, 29, 0.98), rgba(11, 35, 40, 0.98)) padding-box,
    linear-gradient(100deg, #62ddd3, #4aa7df, #6764ed, #62ddd3) border-box;
  background-position: center, center, 0% 50%;
  background-size: auto, auto, 300% 100%;
  box-shadow: 0 28px 80px rgba(0, 7, 15, 0.38), 0 0 0 1px rgba(255, 255, 255, 0.025) inset;
  backdrop-filter: blur(20px);
  transform: translateX(-50%);
  animation:
    cookie-consent-enter 420ms cubic-bezier(0.22, 1, 0.36, 1) both,
    cookie-consent-border-flow 7s linear 420ms infinite;
}

.cookie-consent-accent {
  display: none;
}

.cookie-consent-close {
  position: absolute;
  z-index: 2;
  top: 15px;
  right: 15px;
  display: grid;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 1px solid rgba(151, 184, 187, 0.28);
  border-radius: 9px;
  color: #c9d7da;
  background: rgba(255, 255, 255, 0.035);
  cursor: pointer;
  transition: border-color 180ms ease, color 180ms ease, background 180ms ease, transform 180ms ease;
  place-items: center;
}

.cookie-consent-close span {
  font-size: 23px;
  font-weight: 400;
  line-height: 1;
  transform: translateY(-1px);
}

.cookie-consent-close:hover {
  border-color: rgba(106, 224, 216, 0.62);
  color: #ffffff;
  background: rgba(98, 221, 211, 0.1);
  transform: translateY(-1px);
}

.cookie-consent-close:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 3px;
}

.cookie-consent-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 38px;
}

.cookie-consent-icon {
  display: grid;
  width: 45px;
  height: 45px;
  flex: 0 0 45px;
  border: 1px solid rgba(99, 225, 216, 0.32);
  border-radius: 12px;
  color: #67e1d8;
  background: rgba(98, 221, 211, 0.08);
  place-items: center;
}

.cookie-consent-icon svg {
  width: 23px;
  height: 23px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.7;
}

.cookie-consent-label {
  display: block;
  color: #69ded6;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.13em;
  line-height: 1.4;
  text-transform: uppercase;
}

.cookie-consent h2 {
  margin: 4px 0 0;
  color: #ffffff;
  font-size: 23px;
  font-weight: 720;
  line-height: 1.2;
  letter-spacing: -0.03em;
}

.cookie-consent-copy {
  margin: 14px 0 0;
  color: #c5d3d7;
  font-size: 15px;
  line-height: 1.65;
}

.cookie-consent-copy a {
  color: #73e2da;
  font-weight: 700;
  text-decoration: underline;
  text-decoration-color: rgba(115, 226, 218, 0.45);
  text-underline-offset: 3px;
}

.cookie-consent-preferences {
  display: grid;
  gap: 0;
  margin-top: 15px;
  border-top: 1px solid rgba(145, 198, 197, 0.17);
  border-bottom: 1px solid rgba(145, 198, 197, 0.17);
}

.cookie-consent-preferences label {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 61px;
  cursor: pointer;
}

.cookie-consent-preferences label + label {
  border-top: 1px solid rgba(145, 198, 197, 0.13);
}

.cookie-consent-preferences label > span {
  display: grid;
  gap: 3px;
}

.cookie-consent-preferences strong {
  color: #edf5f6;
  font-size: 13px;
  font-weight: 700;
}

.cookie-consent-preferences small {
  color: #9eb2b7;
  font-size: 12px;
  line-height: 1.45;
}

.cookie-consent-preferences input {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  opacity: 0;
}

.cookie-consent-preferences label > i {
  position: relative;
  width: 38px;
  height: 22px;
  flex: 0 0 38px;
  border: 1px solid #597078;
  border-radius: 999px;
  background: #20323a;
  transition: border-color 180ms ease, background 180ms ease;
}

.cookie-consent-preferences label > i::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #c5d2d6;
  content: "";
  transition: transform 180ms ease, background 180ms ease;
}

.cookie-consent-preferences input:checked + i {
  border-color: #65ddd4;
  background: #0b8d86;
}

.cookie-consent-preferences input:checked + i::after {
  background: #ffffff;
  transform: translateX(16px);
}

.cookie-consent-preferences input:focus-visible + i {
  outline: 2px solid #ffffff;
  outline-offset: 3px;
}

.cookie-consent-preferences input:disabled + i {
  opacity: 0.72;
  cursor: not-allowed;
}

.cookie-consent-actions {
  display: grid;
  grid-template-columns: 1fr 1fr 1.1fr;
  gap: 9px;
  margin-top: 17px;
}

.cookie-consent-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 13px;
  border: 1px solid rgba(151, 184, 187, 0.32);
  border-radius: 8px;
  color: #e5edef;
  background: rgba(255, 255, 255, 0.035);
  font: inherit;
  font-size: 13px;
  font-weight: 750;
  line-height: 1.2;
  cursor: pointer;
  transition: border-color 180ms ease, background 180ms ease, color 180ms ease, transform 180ms ease;
}

.cookie-consent-actions button:hover {
  border-color: rgba(106, 224, 216, 0.62);
  background: rgba(98, 221, 211, 0.08);
  transform: translateY(-1px);
}

.cookie-consent-actions .cookie-consent-accept,
.cookie-consent-actions .cookie-consent-save {
  border-color: #65ded5;
  color: #07171d;
  background: #65ded5;
}

.cookie-consent-actions .cookie-consent-accept:hover,
.cookie-consent-actions .cookie-consent-save:hover {
  color: #061519;
  background: #87e9e2;
}

.cookie-consent-actions button:focus-visible,
.cookie-consent-copy a:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 3px;
}

@keyframes cookie-consent-enter {
  from {
    opacity: 0;
    transform: translate(-50%, 24px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0) scale(1);
  }
}

@keyframes cookie-consent-border-flow {
  from {
    background-position: center, center, 0% 50%;
  }
  to {
    background-position: center, center, 300% 50%;
  }
}

@media (max-width: 620px) {
  .cookie-consent {
    bottom: 12px;
    left: 50%;
    width: calc(100vw - 24px);
    max-height: calc(100svh - 24px);
    overflow-y: auto;
    padding: 20px 18px 18px;
    border-radius: 15px;
  }

  .cookie-consent-icon {
    width: 41px;
    height: 41px;
    flex-basis: 41px;
  }

  .cookie-consent-close {
    top: 12px;
    right: 12px;
  }

  .cookie-consent h2 {
    font-size: 20px;
  }

  .cookie-consent-copy {
    margin-top: 14px;
    font-size: 14px;
    line-height: 1.58;
  }

  .cookie-consent-actions {
    grid-template-columns: 1fr 1fr;
  }

  .cookie-consent-actions .cookie-consent-accept,
  .cookie-consent-actions .cookie-consent-save {
    grid-column: 1 / -1;
    grid-row: 1;
  }
}

@media (max-width: 390px) {
  .cookie-consent-actions {
    grid-template-columns: 1fr;
  }

  .cookie-consent-actions .cookie-consent-accept,
  .cookie-consent-actions .cookie-consent-save {
    grid-column: auto;
    grid-row: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cookie-consent {
    animation: none;
  }
}

