  inset: 0;
  z-index: 0;
  background:
    linear-gradient(115deg, rgba(255, 255, 255, .48), transparent 34%, rgba(90, 182, 175, .06) 64%, transparent),
    radial-gradient(circle at 52% 35%, rgba(255, 255, 255, .7), transparent 30rem);
  content: "";
  pointer-events: none;
}

.webscan-page .webscan-capability-grid article,
.webscan-page .webscan-capability-grid article.is-featured {
  background:
    radial-gradient(circle at 100% 0%, rgba(75, 177, 169, .09), transparent 45%),
