  box-shadow: 0 18px 44px rgba(29, 78, 78, .09);
}

.webscan-page .webscan-capability-grid article.is-featured {
  background:
    radial-gradient(circle at 12% 0%, rgba(67, 188, 176, .15), transparent 50%),
