/* Web Scanner: branded gradient and illustration treatment for reports. */
.webscan-page .webscan-results {
  overflow: hidden;
  border-top: 1px solid rgba(74, 151, 145, .17);
  border-bottom-color: rgba(88, 118, 174, .2);
  background:
    radial-gradient(circle at 84% 18%, rgba(78, 114, 225, .17), transparent 30rem),
    radial-gradient(circle at 10% 88%, rgba(42, 177, 163, .18), transparent 34rem),
    linear-gradient(135deg, #f3faf8 0%, #e7f3f1 48%, #e9edf8 100%);
}

.webscan-page .webscan-results::before {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    linear-gradient(115deg, rgba(255, 255, 255, .46), transparent 35%, rgba(89, 109, 221, .05) 70%, transparent),
    radial-gradient(circle at 52% 42%, rgba(255, 255, 255, .62), transparent 30rem);
  content: "";
  pointer-events: none;
}

.webscan-page .webscan-results .webscan-kicker {
  color: #087a73;
}

.webscan-page .webscan-results-art {
  position: relative;
  width: min(100%, 410px);
  padding: 22px;
  overflow: hidden;
  border: 1px solid rgba(76, 159, 158, .28);
  border-radius: 28px;
  background:
    radial-gradient(circle at 24% 18%, rgba(60, 201, 187, .22), transparent 46%),
    linear-gradient(145deg, rgba(255, 255, 255, .8), rgba(221, 233, 249, .78));
  box-shadow: 0 26px 58px rgba(36, 88, 105, .14), inset 0 1px 0 rgba(255, 255, 255, .76);
}

.webscan-page .webscan-results-art img {
  width: 100%;
  filter: none;
}

.webscan-page .webscan-results-details {
  background: linear-gradient(145deg, rgba(255, 255, 255, .94), rgba(239, 247, 248, .9));
  box-shadow: 0 18px 44px rgba(29, 78, 78, .09);
}

@media (max-width: 1120px) {
  .webscan-page .webscan-results-visual {
    place-items: center;
